// ═══ BASIC USAGE — always try/finally! ═══
ReentrantLock lock = new ReentrantLock();

lock.lock();
try {
    // critical section — balance update
    balance = balance.subtract(amount);
} finally {
    lock.unlock();  // MUST be in finally! Forgetting = permanent deadlock!
}

// ═══ tryLock — non-blocking, returns immediately ═══
if (lock.tryLock()) {
    try { processHighPriority(); }
    finally { lock.unlock(); }
} else {
    processLater();  // lock not available — do something else!
}

// ═══ tryLock with timeout — wait up to N seconds ═══
if (lock.tryLock(5, TimeUnit.SECONDS)) {
    try { settleTradeWithDB(); }
    finally { lock.unlock(); }
} else {
    log.warn("Could not acquire lock in 5 seconds — potential deadlock!");
    alertOps();
}

// ═══ lockInterruptibly — can be interrupted while waiting ═══
try {
    lock.lockInterruptibly();  // if thread is interrupted → InterruptedException!
    try { processTrade(); }
    finally { lock.unlock(); }
} catch (InterruptedException e) {
    Thread.currentThread().interrupt();
    log.info("Lock wait interrupted — shutting down");
}

// ═══ FAIR LOCK — FIFO ordering ═══
ReentrantLock fairLock = new ReentrantLock(true);  // fair = true!
// Longest-waiting thread gets the lock next.
// Without fair: a thread can "barge in" — unfair but faster!
// Fair lock: ~10% slower (maintains a queue), but no starvation.

// ═══ CONDITION — multiple wait-sets ═══
ReentrantLock lock2 = new ReentrantLock();
Condition notEmpty = lock2.newCondition();
Condition notFull = lock2.newCondition();

// Producer:
lock2.lock();
try {
    while (queue.isFull()) notFull.await();  // wait for "not full"
    queue.add(item);
    notEmpty.signal();  // signal "not empty" to consumers
} finally { lock2.unlock(); }

// Consumer:
lock2.lock();
try {
    while (queue.isEmpty()) notEmpty.await();  // wait for "not empty"
    item = queue.remove();
    notFull.signal();  // signal "not full" to producers
} finally { lock2.unlock(); }
// TWO conditions on ONE lock! synchronized only has ONE wait/notify per object.

// ═══ REENTRANT — same thread can lock multiple times ═══
lock.lock();     // hold count = 1
lock.lock();     // hold count = 2 (same thread — reentrant!)
lock.unlock();   // hold count = 1
lock.unlock();   // hold count = 0 — released!
// Must unlock as many times as you locked!
