// ─── File: src/test/java/com/bank/lock/ReentrantLockTest.java ───
package com.bank.lock;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;
import static org.assertj.core.api.Assertions.*;

class ReentrantLockTest {

    // ═══ Basic lock/unlock with finally ═══
    @Test
    void basicLockUnlock() {
        ReentrantLock lock = new ReentrantLock();
        int[] balance = {100000};

        lock.lock();
        try {
            balance[0] -= 50000;
        } finally {
            lock.unlock();
        }
        assertThat(balance[0]).isEqualTo(50000);
    }

    // ═══ tryLock — non-blocking ═══
    @Test
    void tryLock_nonBlocking() {
        ReentrantLock lock = new ReentrantLock();
        lock.lock();  // held by current thread

        // Another attempt in same thread (reentrant):
        assertThat(lock.tryLock()).isTrue();  // reentrant — succeeds!
        lock.unlock();
        lock.unlock();

        // Simulate held by another thread:
        Thread holder = new Thread(() -> {
            lock.lock();
            try { Thread.sleep(1000); } catch (InterruptedException e) { }
            finally { lock.unlock(); }
        });
        holder.start();

        try { Thread.sleep(50); } catch (InterruptedException e) { }
        assertThat(lock.tryLock()).isFalse();  // held by holder → false!
        try { holder.join(); } catch (InterruptedException e) { }
    }

    // ═══ tryLock with timeout ═══
    @Test
    void tryLock_withTimeout() throws InterruptedException {
        ReentrantLock lock = new ReentrantLock();
        lock.lock();

        Thread waiter = new Thread(() -> {
            try {
                boolean acquired = lock.tryLock(200, TimeUnit.MILLISECONDS);
                assertThat(acquired).isFalse();  // timeout! Couldn't acquire in 200ms.
            } catch (InterruptedException e) { }
        });
        waiter.start();
        waiter.join();
        lock.unlock();
    }

    // ═══ Fair lock — FIFO ordering ═══
    @Test
    void fairLock_fifoOrder() throws InterruptedException {
        ReentrantLock fairLock = new ReentrantLock(true);
        assertThat(fairLock.isFair()).isTrue();

        // Fair lock ensures longest-waiting thread gets lock next
        int[] order = new int[3];
        int[] index = {0};
        CountDownLatch allStarted = new CountDownLatch(3);
        CountDownLatch holderReady = new CountDownLatch(1);

        fairLock.lock();
        holderReady.countDown();

        for (int i = 0; i < 3; i++) {
            final int threadId = i;
            new Thread(() -> {
                allStarted.countDown();
                fairLock.lock();
                try { order[index[0]++] = threadId; }
                finally { fairLock.unlock(); }
            }).start();
            Thread.sleep(50);  // ensure ordering of wait queue
        }

        allStarted.await();
        Thread.sleep(100);
        fairLock.unlock();

        Thread.sleep(500);
        // With fair lock: threads acquire in order they waited
        assertThat(order).containsExactly(0, 1, 2);
    }

    // ═══ Condition — producer/consumer ═══
    @Test
    void condition_producerConsumer() throws InterruptedException {
        ReentrantLock lock = new ReentrantLock();
        Condition hasData = lock.newCondition();
        String[] data = {null};

        // Consumer: waits for data
        Thread consumer = new Thread(() -> {
            lock.lock();
            try {
                while (data[0] == null) hasData.await();
                assertThat(data[0]).isEqualTo("TRD-001");
            } catch (InterruptedException e) { }
            finally { lock.unlock(); }
        });
        consumer.start();
        Thread.sleep(100);

        // Producer: provides data and signals
        lock.lock();
        try {
            data[0] = "TRD-001";
            hasData.signal();
        } finally { lock.unlock(); }

        consumer.join(2000);
        assertThat(consumer.isAlive()).isFalse();
    }

    // ═══ Reentrant: same thread can lock multiple times ═══
    @Test
    void reentrant_sameTreadLocksTwice() {
        ReentrantLock lock = new ReentrantLock();
        lock.lock();
        assertThat(lock.getHoldCount()).isEqualTo(1);
        lock.lock();  // reentrant!
        assertThat(lock.getHoldCount()).isEqualTo(2);
        lock.unlock();
        lock.unlock();
        assertThat(lock.isLocked()).isFalse();
    }
}
